    for char in paren_string:
        if char == "(":
            if current_group:
                groups.append(current_group)
            current_group = "("
        elif char == ")":
            current_group += ")"
            groups.append(current_group)
            current_group = ""

    # Step 3: Ensure each group is balanced (properly opened and closed)
    balanced_groups = []
    for group in groups:
        if group.count("(") == group.count(")"):
            balanced_groups.append(group)

    # Step 4: Return a list of separated groups in the order they appear in the input string
    return balanced_groups

